import numpy as np

def select_next_node(current_node, truck_nodes, depot_node, unvisited_nodes, distance_matrix):
    if len(unvisited_nodes) == 0:
        return depot_node

    nodes = list(unvisited_nodes)
    n = len(nodes)
    dist_current = distance_matrix[current_node, nodes]
    dist_sub = distance_matrix[np.ix_(nodes, nodes)]

    scores = np.zeros(n)
    for i, node in enumerate(nodes):
        # distances to all other unvisited nodes
        other_dists = np.delete(dist_sub[i], i)
        if len(other_dists) == 0:
            entropy = 0.0
        else:
            total = np.sum(other_dists)
            if total == 0:
                entropy = 0.0
            else:
                p = other_dists / total
                p = np.clip(p, 1e-12, 1.0)
                entropy = -np.sum(p * np.log(p))
        # modified score: distance * sqrt(entropy)
        scores[i] = dist_current[i] * np.sqrt(entropy) if entropy > 0 else np.inf

    avg_score = np.mean(scores)
    min_idx = np.argmin(scores)
    if scores[min_idx] <= avg_score:
        return nodes[min_idx]
    else:
        return next_node
